import{az as r,P as t,Q as a,aQ as i}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const f=JSON.parse('{"title":"Fiber","description":"","frontmatter":{},"headers":[],"relativePath":"框架/react/react/fiber.md","filePath":"框架/react/react/fiber.md","lastUpdated":1785246304000}'),d={name:"框架/react/react/fiber.md"};function o(l,e,c,n,s,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="fiber" tabindex="-1">Fiber <a class="header-anchor" href="#fiber" aria-label="Permalink to “Fiber”">​</a></h1><p>Fiber 是 React 内部用来管理渲染工作的核心数据结构，也是「可中断渲染」和 <a href="./并发渲染">并发渲染</a> 的基础。</p><p>它不是面向业务的 API，但面试和源码阅读里经常出现。</p><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to “解决什么问题”">​</a></h2><p>Stack Reconciler（旧架构）用递归同步遍历组件树：一旦开始，很难中途停下。复杂页面更新时容易长时间占用主线程。</p><p>Fiber 把更新拆成一个个<strong>工作单元</strong>，让 React 能够：</p><ul><li>暂停当前工作</li><li>稍后继续</li><li>丢弃过时工作，优先处理更紧急的更新</li></ul><h2 id="fiber-节点大致长什么样" tabindex="-1">Fiber 节点大致长什么样 <a class="header-anchor" href="#fiber-节点大致长什么样" aria-label="Permalink to “Fiber 节点大致长什么样”">​</a></h2><p>每个组件 / DOM 节点对应一个 Fiber，常见字段直觉：</p><table tabindex="0"><thead><tr><th>字段直觉</th><th>含义</th></tr></thead><tbody><tr><td><code>type</code> / <code>key</code></td><td>对应元素类型与 key</td></tr><tr><td><code>child</code> / <code>sibling</code> / <code>return</code></td><td>树结构：子节点、兄弟、父节点</td></tr><tr><td><code>alternate</code></td><td>指向另一棵树上的对应节点（双缓冲）</td></tr><tr><td><code>pendingProps</code> / <code>memoizedProps</code></td><td>新 props / 上次渲染的 props</td></tr><tr><td><code>flags</code> / <code>effectTag</code></td><td>标记要插入、更新、删除等副作用</td></tr></tbody></table><p>用链表（child / sibling / return）而不是深递归调用栈，遍历时更容易在单元边界让出主线程。</p><h2 id="双缓冲-current-workinprogress" tabindex="-1">双缓冲（current / workInProgress） <a class="header-anchor" href="#双缓冲-current-workinprogress" aria-label="Permalink to “双缓冲（current / workInProgress）”">​</a></h2><p>React 同时维护两棵概念上的树：</p><ul><li><strong>current</strong>：当前已呈现在屏幕上的 Fiber 树</li><li><strong>workInProgress</strong>：正在构建的下一棵树</li></ul><p>Render 阶段在 workInProgress 上算；Commit 成功后，workInProgress 成为新的 current。</p><p>好处：构建失败或被更高优先级打断时，不影响当前屏幕；算完再一次性切换。</p><h2 id="和工作循环的关系" tabindex="-1">和工作循环的关系 <a class="header-anchor" href="#和工作循环的关系" aria-label="Permalink to “和工作循环的关系”">​</a></h2><p>简化理解：</p><ol><li>从根取出下一个 Fiber 单元</li><li>执行该单元上的工作（开始处理 / Diff 子节点等）</li><li>若还有时间片 → 继续下一个；否则暂停，把控制权还给浏览器</li><li>整棵树 Render 完成后，进入 <a href="./双阶段">Commit</a></li></ol><p>真正「何时跑、跑多久」由 Scheduler 配合优先级决定，详见 <a href="./并发渲染">并发渲染</a>。</p><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p>如果把渲染看成一项工程，Fiber 就是把工程拆成小模块，方便暂停、继续和按优先级重排。</p>',22)])])}const m=r(d,[["render",o]]);export{f as __pageData,m as default};
